-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_core_sample_installment(p_transaction_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transaction_id AND procedure = 'core_sample_installment' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('core_sample_installment', p_transaction_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_core_sample_installment(p_transaction_id text, p_merchant_id text, p_issuer_id text, p_principal bigint, p_currency text, p_subsidy_pct bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    v_subsidy bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transaction_id AND procedure = 'core_sample_installment' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transaction_id AND procedure = 'core_sample_installment' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_transaction_id, 'core_sample_installment')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;

    v_subsidy := ((p_principal * p_subsidy_pct) / 100);

    -- debit merchant_subsidy (acquirer.merchant_balance)
    IF (v_subsidy) < 0 THEN
        RAISE EXCEPTION 'negative money for merchant_subsidy';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('acquirer.merchant_balance', p_merchant_id, p_currency, -(v_subsidy))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(v_subsidy));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_sample_installment', 'merchant_subsidy', 'acquirer.merchant_balance', p_merchant_id, v_subsidy, p_currency, -(v_subsidy), p_transaction_id);

    -- credit issuer_receivable (issuer.promotional_receivable)
    IF (v_subsidy) < 0 THEN
        RAISE EXCEPTION 'negative money for issuer_receivable';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('issuer.promotional_receivable', p_issuer_id, p_currency, v_subsidy)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (v_subsidy);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_sample_installment', 'issuer_receivable', 'issuer.promotional_receivable', p_issuer_id, v_subsidy, p_currency, v_subsidy, p_transaction_id);

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'core_sample_installment' AND idempotency_key = p_transaction_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_transaction_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('core_sample_installment', p_transaction_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
